package com.bank.mentor.service;

import com.bank.mentor.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class MentorService {
    private static final Logger log = Logger.getLogger(MentorService.class.getName());

    public List<Employee> selectMentors(List<Employee> employees) {
        log.info(() -> "Selecting mentors (male, age>30, Sales) from " + employees.size());
        return employees.stream()
                // Department first: cheap, highly selective → short-circuits the rest.
                .filter(e -> "Sales".equals(e.getDepartment())
                          && e.getAge() > 30
                          && "M".equals(e.getGender()))
                .collect(Collectors.toList());
    }
}
