        List<Employee> staff = List.of(
            new Employee("Rajesh", "M", 34, "Sales"),
            new Employee("Arjun",  "M", 28, "Sales"),
            new Employee("Priya",  "F", 35, "Sales"),
            new Employee("Mohan",  "M", 45, "IT"),
            new Employee("Karan",  "M", 41, "Sales")
        );

        new MentorService().selectMentors(staff)
            .forEach(e -> log.info(() -> "Mentor selected: " + e));
    }
}
